\begin{aligned}
\mathrm{EqRel}_{T,A}(S)\leftrightarrow{}&S\subseteq\mathrm{Hom}_{\mathcal E}(T,A)^2\land\forall u\in\mathrm{Hom}_{\mathcal E}(T,A)\ ((u,u)\in S)\\
&\land\forall u,v\in\mathrm{Hom}_{\mathcal E}(T,A)\ ((u,v)\in S\to(v,u)\in S)\\
&\land\forall u,v,w\in\mathrm{Hom}_{\mathcal E}(T,A)\ (((u,v)\in S\land(v,w)\in S)\to(u,w)\in S).
\end{aligned}

\begin{aligned}
\mathrm{IsInternalEquivalenceRelation}_{\mathcal E}(R,r_1,r_2,A)\leftrightarrow{}&A,R\in\mathrm{Ob}(\mathcal E)\land r_1,r_2\in\mathrm{Hom}_{\mathcal E}(R,A)\\
&\land\forall T\in\mathrm{Ob}(\mathcal E)\ \forall u,v\in\mathrm{Hom}_{\mathcal E}(T,R)\ ((r_1\circ u=r_1\circ v\land r_2\circ u=r_2\circ v)\to u=v)\\
&\land\forall T\in\mathrm{Ob}(\mathcal E)\ \mathrm{EqRel}_{T,A}(\mathrm{Rel}_{\mathcal E;A,R,r_1,r_2}(T)).
\end{aligned}
